    $q("#t-wi-entry-pane-title").text(title);
    $q("#t-wi-entry-pane-badge").text(isActive ? "\u5DF2\u6FC0\u6D3B" : "\u672A\u6FC0\u6D3B").removeClass("active inactive").addClass(isActive ? "active" : "inactive");
